void degree(int n, int m, int from[], int to[], int in[], int out[]) {
    for (int v = 1; v <= n; v++) in[v] = out[v] = 0;
    for (int k = 0; k < m; k++) {   /* 第 k 條弧 (from[k], to[k]) */
        out[from[k]]++;
        in[to[k]]++;
    }
}

