struct node { struct node *LeftChild; int Data; struct node *RightChild; };

int countLeaf(struct node *T) {
    if (T == NULL) return 0;                                  /* 空樹 */
    if (T->LeftChild == NULL && T->RightChild == NULL) return 1;  /* 葉節點 */
    return countLeaf(T->LeftChild) + countLeaf(T->RightChild);
}
